#include <syslog.h>
#include <string.h>

void safe_log(const char *message) {
    // Assuming message is a user-provided string
    // Sanitize the message to prevent injection attacks
    char safe_message[1024];
    strncpy(safe_message, message, sizeof(safe_message) - 1);
    safe_message[sizeof(safe_message) - 1] = '\0'; // Ensure null-termination

    // Log the sanitized message
    syslog(LOG_DEBUG, "%s", safe_message);
}

int main() {
    const char *user_input = "User provided log message";
    safe_log(user_input);
    return 0;
}
